import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate, Outlet, type Location, Link } from 'react-router-dom';
import { Cpu, Users, Shield, BarChart, Settings, ChevronLeft, X, RotateCcw } from 'lucide-react';
import { cn } from '@utils/helpers';
import { Tooltip } from '@shared/components/Tooltip';
import { motion, AnimatePresence } from 'motion/react';
import { AdminHeader } from './AdminHeader';
import { createPortal } from 'react-dom';
import { useTheme } from '@hooks/useTheme';

const ADMIN_NAV = [
  { id: 'motor-ia', icon: Cpu, labelKey: 'automation.title', path: '/admin/motor-ia', disabled: false },
  { id: 'users', icon: Users, labelKey: 'admin.users', path: '/admin/users', disabled: true },
  { id: 'moderation', icon: Shield, labelKey: 'admin.moderation', path: '/admin/moderation', disabled: true },
  { id: 'analytics', icon: BarChart, labelKey: 'admin.analytics', path: '/admin/analytics', disabled: true },
  { id: 'settings', icon: Settings, labelKey: 'admin.settings', path: '/admin/settings', disabled: true },
] as const;

interface AdminLayoutContentProps {
  collapsed: boolean;
  onCollapseChange: (collapsed: boolean) => void;
  location: Location;
}

export const AdminLayoutContent = ({ collapsed, onCollapseChange, location }: AdminLayoutContentProps) => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const theme = useTheme();

  const [mobileOpen, setMobileOpen] = useState(false);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const isActive = (path: string) => location.pathname === path || location.pathname.startsWith(path + '/');

  const toggleCollapsed = () => onCollapseChange(!collapsed);

  const sidebarWidth = collapsed ? 'w-14' : 'w-72';

  // Desktop sidebar (no fixed, part of flex)
  const desktopSidebar = (
    <aside
      className={cn(
        'hidden lg:flex lg:flex-col bg-card border-r border-border-main/10 transition-all duration-200',
        sidebarWidth,
        'h-screen'
      )}
      aria-label={t('admin.sidebar.navigation')}
    >
      <div className="flex h-16 items-center justify-between px-3 border-b border-border-main/10">
        <div className="flex items-center justify-center w-full">
          <Link
            to="/admin/motor-ia"
            onClick={(e) => {
              if (collapsed) {
                e.preventDefault();
                toggleCollapsed();
              }
            }}
            className="flex items-center justify-center"
            aria-label={t('admin.sidebar.title')}
          >
            {/* Desktop expanded: horizontal logo */}
            {!collapsed && (
              <img
                src={theme === 'dark' ? '/icons/eTribunal-logo-horizontal-bn.png' : '/icons/eTribunal-logo-horizontal.png'}
                alt="eTribunal"
                className="hidden lg:block h-8 w-auto transition-opacity"
              />
            )}
            {/* Desktop collapsed or mobile: isotipo */}
            <img
              src={theme === 'dark' ? '/icons/eTribunal-isotipo-bn.png' : '/icons/eTribunal-isotipo.png'}
              alt="eTribunal"
              className={cn(
                'h-8 w-auto transition-opacity',
                'lg:hidden',
                collapsed && 'lg:block',
                !collapsed && 'lg:hidden'
              )}
            />
          </Link>
        </div>
        {!collapsed && (
          <button
            onClick={toggleCollapsed}
            className="lg:flex ml-auto w-8 h-8 rounded-lg flex items-center justify-center text-text-muted hover:bg-border-main/10"
            aria-label={t('admin.sidebar.collapse')}
          >
            <ChevronLeft className="w-5 h-5" />
          </button>
        )}
      </div>

      <nav className="flex-1 overflow-y-auto py-4 px-2 subtle-scrollbar">
        {ADMIN_NAV.filter((item) => !item.disabled).map((item) => {
          const active = isActive(item.path);
          const Icon = item.icon;
          const label = t(item.labelKey);
          let stateClass = 'text-text-muted hover:bg-border-main/5 hover:text-text-main';
          if (active) stateClass = 'bg-primary/10 text-primary';
          else if (item.disabled) stateClass = 'text-text-muted/40 cursor-not-allowed';
          const buttonContent = (
            <button
              onClick={() => {
                if (!item.disabled) navigate(item.path);
              }}
              disabled={item.disabled}
              className={cn(
                'w-full flex items-center gap-4 px-3 py-3 rounded-xl transition-all group',
                stateClass,
                collapsed && 'justify-center'
              )}
              aria-current={active ? 'page' : undefined}
              aria-disabled={item.disabled}
            >
              <Icon className={cn('w-5 h-5 flex-shrink-0 transition-transform group-hover:scale-110', active && 'text-primary', item.disabled && 'opacity-40')} />
              {!collapsed && (
                <span className="text-sm font-black uppercase tracking-widest italic truncate">
                  {label}
                </span>
              )}
            </button>
          );

          return collapsed ? (
            <Tooltip key={item.id} content={label} position="right">
              {buttonContent}
            </Tooltip>
          ) : (
            <div key={item.id}>{buttonContent}</div>
          );
        })}
        <div className="border-t border-border-main/10 my-2" />
        <button
          onClick={() => navigate('/')}
          className={cn(
            'w-full flex items-center gap-4 px-3 py-3 rounded-xl transition-all group',
            'text-text-muted hover:bg-border-main/5 hover:text-text-main',
            collapsed && 'justify-center'
          )}
        >
          <RotateCcw className="w-5 h-5 flex-shrink-0 transition-transform group-hover:scale-110" />
          {!collapsed && (
            <span className="text-sm font-black uppercase tracking-widest italic truncate">
              {t('admin.sidebar.backToFeed')}
            </span>
          )}
        </button>

      </nav>

      <div className="p-4 border-t border-border-main/10">
        {!collapsed && (
          <p className="text-xs text-text-muted text-center uppercase tracking-wider">
            {t('admin.sidebar.version')}
          </p>
        )}
      </div>
    </aside>
  );

  // Mobile drawer - rendered via portal to avoid z-index issues
  const mobileDrawer = mounted ? createPortal(
    <AnimatePresence>
      {mobileOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 lg:hidden bg-black/50"
            onClick={() => setMobileOpen(false)}
            aria-hidden="true"
          />
          <motion.aside
            initial={{ x: -300 }}
            animate={{ x: 0 }}
            exit={{ x: -300 }}
            transition={{ type: 'spring', damping: 25, stiffness: 300 }}
            className="fixed inset-y-0 left-0 z-[60] lg:hidden w-72 bg-card border-r border-border-main/10 flex flex-col"
            role="dialog"
            aria-label={t('admin.sidebar.navigation')}
          >
            <div className="flex h-16 items-center justify-between px-4 border-b border-border-main/10">
              <span className="text-lg font-black uppercase tracking-widest italic text-primary">
                {t('admin.sidebar.title')}
              </span>
              <button
                onClick={() => setMobileOpen(false)}
                className="w-8 h-8 rounded-lg flex items-center justify-center text-text-muted hover:bg-border-main/10"
                aria-label={t('admin.sidebar.close')}
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <nav className="flex-1 overflow-y-auto py-4 px-2 subtle-scrollbar">
              {ADMIN_NAV.filter((item) => !item.disabled).map((item) => {
                const active = isActive(item.path);
                const Icon = item.icon;
                const label = t(item.labelKey);
                let stateClass = 'text-text-muted hover:bg-border-main/5 hover:text-text-main';
                if (active) stateClass = 'bg-primary/10 text-primary';
                else if (item.disabled) stateClass = 'text-text-muted/40 cursor-not-allowed';
                return (
                  <button
                    key={item.id}
                    onClick={() => {
                      if (!item.disabled) navigate(item.path);
                      setMobileOpen(false);
                    }}
                    disabled={item.disabled}
                    className={cn(
                      'w-full flex items-center gap-4 px-3 py-3 rounded-xl transition-all group',
                      stateClass
                    )}
                    aria-current={active ? 'page' : undefined}
                    aria-disabled={item.disabled}
                  >
                    <Icon className={cn('w-5 h-5 flex-shrink-0 transition-transform group-hover:scale-110', active && 'text-primary', item.disabled && 'opacity-40')} />
                    <span className="text-sm font-black uppercase tracking-widest italic truncate">
                      {label}
                    </span>
                  </button>
                );
              })}
              <div className="border-t border-border-main/10 my-2" />
              <button
                onClick={() => {
                  navigate('/');
                  setMobileOpen(false);
                }}
                className={cn(
                  'w-full flex items-center gap-4 px-3 py-3 rounded-xl transition-all group',
                  'text-text-muted hover:bg-border-main/5 hover:text-text-main'
                )}
              >
                <RotateCcw className="w-5 h-5 flex-shrink-0 transition-transform group-hover:scale-110" />
                <span className="text-sm font-black uppercase tracking-widest italic truncate">
                  {t('admin.sidebar.backToFeed')}
                </span>
              </button>
            </nav>

            <div className="p-4 border-t border-border-main/10">
              <p className="text-xs text-text-muted text-center uppercase tracking-wider">
                {t('admin.sidebar.version')}
              </p>
            </div>
          </motion.aside>
        </>
      )}
    </AnimatePresence>
    , document.body) : null;

  // Mobile menu button
  return (
    <div className="h-screen flex flex-col overflow-hidden">
      {/* Desktop: flex row with sidebar + content */}
      <div className="hidden lg:flex h-full w-full">
        {desktopSidebar}
        <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
          <AdminHeader titleKey={getTitleKey(location.pathname)} />
          <main className="flex-1 p-4 md:p-6 max-w-7xl mx-auto w-full overflow-y-auto subtle-scrollbar">
            <Outlet />
          </main>
        </div>
      </div>

      {/* Mobile: stacked layout with drawer portal */}
      <div className="lg:hidden h-full flex flex-col">
        {mobileDrawer}
        <div className="flex-1 flex flex-col overflow-hidden">
          <AdminHeader
            titleKey={getTitleKey(location.pathname)}
            onMobileMenuToggle={() => setMobileOpen(true)}
            showMobileMenuButton
          />
          <main className="flex-1 p-4 md:p-6 max-w-7xl mx-auto w-full overflow-y-auto subtle-scrollbar">
            <Outlet />
          </main>
        </div>
      </div>
    </div>
  );
};

function getTitleKey(pathname: string): string | undefined {
  if (pathname === '/admin/motor-ia' || pathname.startsWith('/admin/motor-ia/')) {
    return 'automation.title';
  }
  if (pathname === '/admin/users' || pathname.startsWith('/admin/users/')) {
    return 'admin.users';
  }
  if (pathname === '/admin/moderation' || pathname.startsWith('/admin/moderation/')) {
    return 'admin.moderation';
  }
  if (pathname === '/admin/analytics' || pathname.startsWith('/admin/analytics/')) {
    return 'admin.analytics';
  }
  if (pathname === '/admin/settings' || pathname.startsWith('/admin/settings/')) {
    return 'admin.settings';
  }
  return undefined;
}

