  useGetCommentsQuery: (arg: unknown, opts?: unknown) => mocks.mockUseGetCommentsQuery(arg, opts),
  useGetNewCommentsCountQuery: (arg: unknown, opts?: unknown) =>
    mocks.mockUseGetNewCommentsCountQuery(arg, opts),
