    id,
    user: 'juez1',
    userId: 'u1',
    avatar: 'http://x/a.png',
    text: `Comentario ${id}`,
    timestamp: 'hace 1 d├¡a',
    createdAt,
    reactions: { LIKE: 0, LOVE: 0, ANGRY: 0 },
    userReaction: null,
    likes: 0,
    isOwner: false,
    contentLanguage: undefined,
    replies_count: 0,
    reactions_count: 0,
