/**
 * ============================================
 * hooks/useCommentsData.ts ÔÇö Orquestaci├│n de comentarios con RTK Query
 * ============================================
 *
 * Reemplaza hooks/useComments (estado local). Fuente de datos:
 * commentsApi (RTK Query), con una sola entrada de cache por caseId.
 *
 * ┬┐Qu├® orquesta?
 *   - getComments: p├ígina inicial + p├íginas anteriores (before) +
 *     comentarios nuevos (after) v├¡a comentariosApi.
 *   - getNewCommentsCount: polling cada 15s (pausado si la pesta├▒a est├í
 *     oculta o mientras hay comentarios por mostrar).
 *   - Mutaciones addComment/updateComment/deleteComment, con parcheo
 *     autom├ítico de la cache por commentsApi.
 */

import { useCallback, useEffect, useState } from 'react';
import type { CaseComment } from '@typings/index';
import { useAppDispatch } from '@redux/hooks';
import {
  COMMENTS_PAGE_SIZE,
  NEW_COMMENTS_LIMIT,
  commentsApi,
  useAddCommentMutation,
  useDeleteCommentMutation,
  useGetCommentsQuery,
  useGetNewCommentsCountQuery,
  useUpdateCommentMutation,
} from '@redux/services/commentsApi';

export interface UseCommentsDataReturn {
  visibleComments: CaseComment[];
  pendingCount: number;
  hasMore: boolean;
  nextCursor: string | null;
  isFetching: boolean;
  addComment: (
    caseId: string,
    content: string,
    parentId?: string
  ) => Promise<CaseComment>;
  updateComment: (commentId: string, content: string) => Promise<void>;
  deleteComment: (commentId: string) => Promise<void>;
  fetchOlderComments: (caseId: string) => void;
  showNewComments: () => void;
  hideNewCommentsIndicator: () => void;
}

const NEW_COMMENTS_POLL_MS = 15_000;

export function useCommentsData(
  caseId?: string
): UseCommentsDataReturn {
  const dispatch = useAppDispatch();

  const [pendingCount, setPendingCount] = useState(0);
  const [pendingSince, setPendingSince] = useState<string | null>(null);

  // Al cambiar de caso se limpia el estado de "comentarios nuevos"
  // pendientes para no arrastrarlos entre detalles.
  useEffect(() => {
    setPendingCount(0);
    setPendingSince(null);
  }, [caseId]);

  // ============================================================
  // Lista de comentarios (p├ígina inicial + paginaci├│n por cursor)
  // ============================================================
  const {
    data,
    isFetching,
  } = useGetCommentsQuery(
    { caseId: caseId ?? '', limit: COMMENTS_PAGE_SIZE },
    { skip: !caseId }
  );

  const visibleComments = data?.comments ?? [];
  const hasMore = data?.hasMore ?? false;
  const nextCursor = data?.nextCursor ?? null;

  // El comentario m├ís nuevo visible define el cursor `since` de polling.
  const newestTimestamp =
    visibleComments.length > 0 ? visibleComments[0].createdAt : undefined;

  // ============================================================
  // Polling de comentarios nuevos (15s, pausado con pendientes)
  // ============================================================
  const { data: newCountData } = useGetNewCommentsCountQuery(
    { caseId: caseId ?? '', since: newestTimestamp ?? '' },
    {
      skip: !caseId || !newestTimestamp,
      pollingInterval:
        caseId && newestTimestamp && pendingCount === 0
          ? NEW_COMMENTS_POLL_MS
          : 0,
      skipPollingIfUnfocused: true,
    }
  );

  // El contador solo puede ser > 0 mientras estamos mostrando
  // comentarios que a├║n no aparecen en pantalla (sin pendientes).
  useEffect(() => {
    const count = newCountData?.count ?? 0;
    if (count > 0) {
      setPendingCount(count);
      setPendingSince(newestTimestamp ?? null);
    }
  }, [newCountData?.count, newestTimestamp]);

  // ============================================================
  // Acciones
  // ============================================================

  const loadOlderSub = useCallback(
    (caseIdToLoad: string, before: string) => {
      const result = dispatch(
        commentsApi.endpoints.getComments.initiate({
          caseId: caseIdToLoad,
          before,
          limit: COMMENTS_PAGE_SIZE,
        })
      );
      result.unsubscribe();
    },
    [dispatch]
  );

  const fetchOlderComments = useCallback(
    (caseIdToLoad: string) => {
      if (!nextCursor || isFetching) return;
      loadOlderSub(caseIdToLoad, nextCursor);
    },
    [nextCursor, isFetching, loadOlderSub]
  );

  const showNewComments = useCallback(() => {
    if (!caseId || !pendingSince) return;
    const since = pendingSince;
    setPendingCount(0);
    setPendingSince(null);
    const result = dispatch(
      commentsApi.endpoints.getComments.initiate({
        caseId,
        after: since,
        limit: NEW_COMMENTS_LIMIT,
      })
    );
    result.unsubscribe();
  }, [dispatch, caseId, pendingSince]);

  const hideNewCommentsIndicator = useCallback(() => {
    setPendingCount(0);
    setPendingSince(null);
  }, []);

  const [runAddComment] = useAddCommentMutation();
  const addComment = useCallback(
    async (caseIdTarget: string, content: string, parentId?: string) => {
      return runAddComment({ caseId: caseIdTarget, content, parentId }).unwrap();
    },
    [runAddComment]
  );

  const [runUpdateComment] = useUpdateCommentMutation();
  const updateComment = useCallback(
    async (commentId: string, content: string) => {
      await runUpdateComment({ commentId, content }).unwrap();
    },
    [runUpdateComment]
  );

  const [runDeleteComment] = useDeleteCommentMutation();
  const deleteComment = useCallback(
    async (commentId: string) => {
      await runDeleteComment({ commentId }).unwrap();
    },
    [runDeleteComment]
  );

  return {
    visibleComments,
    pendingCount,
    hasMore,
    nextCursor,
    isFetching,
    addComment,
    updateComment,
    deleteComment,
    fetchOlderComments,
    showNewComments,
    hideNewCommentsIndicator,
  };
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useContentTranslation } from './useContentTranslation';

const mockTranslateCaseApi = vi.fn();
const mockTranslateCommentApi = vi.fn();

vi.mock('../features/translation/services/translationApi', () => ({
  translateCaseApi: (...args: any[]) => mockTranslateCaseApi(...args),
  translateCommentApi: (...args: any[]) => mockTranslateCommentApi(...args),
}));

describe('useContentTranslation', () => {
  beforeEach(() => {
    mockTranslateCaseApi.mockReset();
    mockTranslateCommentApi.mockReset();
  });

  it('deber├¡a devolver estado inicial', () => {
    const { result } = renderHook(() => useContentTranslation());

    expect(result.current.isTranslating).toBe(false);
    expect(result.current.translatedCase).toBeNull();
    expect(result.current.translatedComment).toBeNull();
    expect(result.current.showTranslation).toBe(false);
  });

  it('translateCase deber├¡a traducir un caso', async () => {
    const { result } = renderHook(() => useContentTranslation());

    const translated = {
      id: 't1',
      sourceLanguage: 'es',
      targetLanguage: 'en',
      title: 'My Case',
      sideA: 'Story A',
      sideB: null,
      sideASubtitle: null,
      sideBSubtitle: null,
      bothWrongSubtitle: null,
    };

    mockTranslateCaseApi.mockResolvedValue(translated);

    let res: any;
    await act(async () => {
      res = await result.current.translateCase('case-1', 'en');
    });

    expect(res).toEqual(translated);
    expect(result.current.translatedCase).toEqual(translated);
    expect(result.current.showTranslation).toBe(true);
    expect(mockTranslateCaseApi).toHaveBeenCalledWith('case-1', 'en');
  });

  it('translateComment deber├¡a traducir un comentario', async () => {
    const { result } = renderHook(() => useContentTranslation());

    const translated = {
      id: 't1',
      commentId: 'c1',
      sourceLanguage: 'es',
      targetLanguage: 'en',
      content: 'Hello world',
    };

    mockTranslateCommentApi.mockResolvedValue(translated);

    let res: any;
    await act(async () => {
      res = await result.current.translateComment('comment-1', 'en');
    });

    expect(res).toEqual(translated);
    expect(result.current.translatedComment).toEqual(translated);
    expect(result.current.showTranslation).toBe(true);
  });

  it('showOriginal y showTranslated deber├¡an alternar visibilidad', () => {
    const { result } = renderHook(() => useContentTranslation());

    act(() => {
      result.current.showTranslated();
    });
    expect(result.current.showTranslation).toBe(true);

    act(() => {
      result.current.showOriginal();
    });
    expect(result.current.showTranslation).toBe(false);
  });

  it('setTranslatedCase deber├¡a actualizar el estado', () => {
    const { result } = renderHook(() => useContentTranslation());

    act(() => {
      result.current.setTranslatedCase({ id: 't1' } as any);
    });

    expect(result.current.translatedCase).toEqual({ id: 't1' });
  });

  it('setTranslatedComment deber├¡a actualizar el estado', () => {
    const { result } = renderHook(() => useContentTranslation());

    act(() => {
      result.current.setTranslatedComment({ id: 't1' } as any);
    });

    expect(result.current.translatedComment).toEqual({ id: 't1' });
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useInfiniteScroll } from './useInfiniteScroll';

vi.mock('react', async () => {
  const actual = await vi.importActual<typeof import('react')>('react');
  return {
    ...actual,
    useRef: (initialValue: any) => {
      if (initialValue === null) {
        return { current: document.createElement('div') };
      }
      return actual.useRef(initialValue);
    },
  };
});

describe('useInfiniteScroll', () => {
  let observeMock: ReturnType<typeof vi.fn>;
  let unobserveMock: ReturnType<typeof vi.fn>;
  let disconnectMock: ReturnType<typeof vi.fn>;
  let intersectionCallback!: (entries: IntersectionObserverEntry[]) => void;

  beforeEach(() => {
    observeMock = vi.fn();
    unobserveMock = vi.fn();
    disconnectMock = vi.fn();

    vi.stubGlobal('IntersectionObserver', class {
      constructor(cb: (entries: IntersectionObserverEntry[]) => void) {
        intersectionCallback = cb;
      }
      observe = observeMock;
      unobserve = unobserveMock;
      disconnect = disconnectMock;
    });
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it('deber├¡a devolver un ref', () => {
    const { result } = renderHook(() => useInfiniteScroll({
      onLoadMore: vi.fn(),
      hasMore: true,
      isLoading: false,
    }));

    expect(result.current.loadMoreRef).toBeDefined();
  });

  it('deber├¡a llamar onLoadMore cuando el centinela se intersecta', () => {
    const loadMore = vi.fn();
    renderHook(() => useInfiniteScroll({
      onLoadMore: loadMore,
      hasMore: true,
      isLoading: false,
    }));

    act(() => {
      intersectionCallback([{ isIntersecting: true } as IntersectionObserverEntry]);
    });

    expect(loadMore).toHaveBeenCalledTimes(1);
  });

  it.each([
    { name: 'NO deber├¡a llamar onLoadMore si hasMore es false', hasMore: false, isLoading: false, intersecting: true },
    { name: 'NO deber├¡a llamar onLoadMore si isLoading es true', hasMore: true, isLoading: true, intersecting: true },
    { name: 'NO deber├¡a llamar onLoadMore si no est├í intersectando', hasMore: true, isLoading: false, intersecting: false },
  ])('$name', ({ hasMore, isLoading, intersecting }) => {
    const loadMore = vi.fn();
    renderHook(() => useInfiniteScroll({
      onLoadMore: loadMore,
      hasMore,
      isLoading,
    }));

    act(() => {
      intersectionCallback([{ isIntersecting: intersecting } as IntersectionObserverEntry]);
    });

    expect(loadMore).not.toHaveBeenCalled();
  });

  it('deber├¡a llamar onLoadMore solo una vez si sigue intersectando (lock)', () => {
    const loadMore = vi.fn();
    renderHook(() => useInfiniteScroll({
      onLoadMore: loadMore,
      hasMore: true,
      isLoading: false,
    }));

    act(() => {
      intersectionCallback([{ isIntersecting: true } as IntersectionObserverEntry]);
    });

    act(() => {
      intersectionCallback([{ isIntersecting: true } as IntersectionObserverEntry]);
    });

    expect(loadMore).toHaveBeenCalledTimes(1);
  });

  it('deber├¡a desconectar el observer al desmontar', () => {
    const { unmount } = renderHook(() => useInfiniteScroll({
      onLoadMore: vi.fn(),
      hasMore: true,
      isLoading: false,
    }));

    unmount();

    expect(disconnectMock).toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useNotifications } from './useNotifications';
import { authStorage } from '@api/client';
import { requestCache } from '@shared/hooks/useApiCache';

const mockGet = vi.fn();
const mockPatch = vi.fn();

vi.mock('@api/client', () => ({
  apiClient: {
    get: (...args: any[]) => mockGet(...args),
    patch: (...args: any[]) => mockPatch(...args),
  },
  authStorage: {
    isAuthenticated: vi.fn(() => true),
    getAccessToken: vi.fn(() => 'token-xyz'),
  },
}));

vi.mock('@shared/hooks/useApiCache', () => ({
  requestCache: {
    get: vi.fn(() => null),
    set: vi.fn(),
    invalidatePattern: vi.fn(),
  },
}));

function makeNotification(id: string, overrides = {}) {
  return {
    id,
    type: 'vote',
    payload: {},
    is_read: false,
    created_at: '2024-01-01T00:00:00Z',
    actor_id: null,
    actor_username: null,
    actor_avatar: null,
    ...overrides,
  };
}

describe('useNotifications', () => {
  beforeEach(() => {
    mockGet.mockReset();
    mockPatch.mockReset();
    (requestCache.get as any).mockClear();
    (requestCache.set as any).mockClear();
    (requestCache.invalidatePattern as any).mockClear();
  });

  it('deber├¡a devolver estado inicial', () => {
    const { result } = renderHook(() => useNotifications());

    expect(result.current.notifications).toEqual([]);
    expect(result.current.total).toBe(0);
    expect(result.current.unreadCount).toBe(0);
    expect(result.current.isLoading).toBe(false);
  });

  it('fetchNotifications deber├¡a obtener notificaciones', async () => {
    const { result } = renderHook(() => useNotifications());

    mockGet.mockResolvedValue({
      notifications: [makeNotification('n1'), makeNotification('n2')],
      total: 2,
      unread_count: 1,
    });

    await act(async () => {
      await result.current.fetchNotifications();
    });

    expect(result.current.notifications).toHaveLength(2);
    expect(result.current.total).toBe(2);
    expect(result.current.unreadCount).toBe(1);
    expect(mockGet).toHaveBeenCalledWith('/notifications?skip=0&take=20');
  });

  it('fetchNotifications deber├¡a soportar paginaci├│n', async () => {
    const { result } = renderHook(() => useNotifications());

    mockGet.mockResolvedValue({ notifications: [], total: 0, unread_count: 0 });

    await act(async () => {
      await result.current.fetchNotifications(10, 5);
    });

    expect(mockGet).toHaveBeenCalledWith('/notifications?skip=10&take=5');
  });

  it('markAsRead deber├¡a marcar notificaci├│n como le├¡da', async () => {
    const { result } = renderHook(() => useNotifications());

    mockGet.mockResolvedValue({
      notifications: [makeNotification('n1'), makeNotification('n2')],
      total: 2,
      unread_count: 2,
    });

    await act(async () => {
      await result.current.fetchNotifications();
    });

    mockPatch.mockResolvedValue(undefined);

    await act(async () => {
      await result.current.markAsRead('n1');
    });

    expect(result.current.notifications[0].is_read).toBe(true);
