  it('markAllAsRead deber├¡a marcar todas como le├¡das', async () => {
    const { result } = renderHook(() => useNotifications());

    mockGet.mockResolvedValue({
      notifications: [makeNotification('n1'), makeNotification('n2', { is_read: false })],
      total: 2,
      unread_count: 2,
    });

    await act(async () => {
      await result.current.fetchNotifications();
    });

    mockPatch.mockResolvedValue(undefined);

    await act(async () => {
      await result.current.markAllAsRead();
    });

    expect(result.current.notifications.every(n => n.is_read)).toBe(true);
    expect(result.current.unreadCount).toBe(0);
    expect(mockPatch).toHaveBeenCalledWith('/notifications/read-all', {});
  });

  it('fetchUnreadCount deber├¡a obtener conteo de no le├¡das', async () => {
    const { result } = renderHook(() => useNotifications());

    mockGet.mockResolvedValue({ unread_count: 5 });

    await act(async () => {
      await result.current.fetchUnreadCount();
    });

    expect(result.current.unreadCount).toBe(5);
    expect(mockGet).toHaveBeenCalledWith('/notifications/unread-count');
  });

  it('fetchNotifications no llama API si no autenticado', async () => {
    (authStorage.isAuthenticated as any).mockReturnValueOnce(false);
    const { result } = renderHook(() => useNotifications());

    await act(async () => {
      await result.current.fetchNotifications();
    });

    expect(mockGet).not.toHaveBeenCalled();
    expect(result.current.isLoading).toBe(false);
  });

  it('markAsRead no llama API si no autenticado', async () => {
    (authStorage.isAuthenticated as any).mockReturnValueOnce(false);
    const { result } = renderHook(() => useNotifications());

    await act(async () => {
      await result.current.markAsRead('n1');
    });

    expect(mockPatch).not.toHaveBeenCalled();
  });

  it('markAllAsRead no llama API si no autenticado', async () => {
    (authStorage.isAuthenticated as any).mockReturnValueOnce(false);
    const { result } = renderHook(() => useNotifications());

    await act(async () => {
      await result.current.markAllAsRead();
    });

    expect(mockPatch).not.toHaveBeenCalled();
  });

  it('fetchUnreadCount no llama API si no autenticado', async () => {
    (authStorage.isAuthenticated as any).mockReturnValueOnce(false);
    const { result } = renderHook(() => useNotifications());

    await act(async () => {
      await result.current.fetchUnreadCount();
    });

    expect(mockGet).not.toHaveBeenCalled();
    expect(result.current.unreadCount).toBe(0);
  });

  it('fetchNotifications usa cach├® cuando est├í disponible', async () => {
    (requestCache.get as any).mockReturnValueOnce({
      notifications: [makeNotification('n1'), makeNotification('n2')],
      total: 2,
      unread_count: 0,
    });
    const { result } = renderHook(() => useNotifications());

    await act(async () => {
      await result.current.fetchNotifications();
    });

    expect(result.current.notifications).toHaveLength(2);
    expect(result.current.total).toBe(2);
    expect(result.current.unreadCount).toBe(0);
    expect(mockGet).not.toHaveBeenCalled();
  });

  it('fetchUnreadCount usa cach├® cuando est├í disponible', async () => {
    (requestCache.get as any).mockReturnValueOnce(3);
    const { result } = renderHook(() => useNotifications());

    await act(async () => {
      await result.current.fetchUnreadCount();
    });

    expect(result.current.unreadCount).toBe(3);
    expect(mockGet).not.toHaveBeenCalled();
  });

  it('markAsRead maneja error de API', async () => {
    const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
    const { result } = renderHook(() => useNotifications());

    mockGet.mockResolvedValue({
      notifications: [makeNotification('n1')],
      total: 1,
      unread_count: 1,
    });

    await act(async () => {
      await result.current.fetchNotifications();
    });

    mockPatch.mockRejectedValue(new Error('Network error'));

    await act(async () => {
      await result.current.markAsRead('n1');
    });

    expect(result.current.notifications[0].is_read).toBe(false);
    expect(result.current.unreadCount).toBe(1);
    expect(consoleSpy).toHaveBeenCalledWith('Error marking notification as read:', expect.any(Error));
    consoleSpy.mockRestore();
  });

  it('fetchNotifications guarda en cach├® la respuesta', async () => {
    const { result } = renderHook(() => useNotifications());
    const response = {
      notifications: [makeNotification('n1')],
      total: 1,
      unread_count: 0,
    };

    mockGet.mockResolvedValue(response);

    await act(async () => {
      await result.current.fetchNotifications();
    });

    expect(requestCache.set).toHaveBeenCalledWith(expect.stringContaining('notifications:'), response);
  });

  it('markAsRead invalida cach├® de notificaciones', async () => {
    const { result } = renderHook(() => useNotifications());

    mockPatch.mockResolvedValue(undefined);

    await act(async () => {
      await result.current.markAsRead('n1');
    });

    expect(requestCache.invalidatePattern).toHaveBeenCalledWith('notifications:');
  });
});

import { useState, useCallback } from 'react';
import { apiClient, authStorage } from '@api/client';
import { requestCache } from '@shared/hooks/useApiCache';

interface Notification {
  id: string;
  type: string;
  payload: any;
  is_read: boolean;
  created_at: string;
  actor_id: string | null;
  actor_username: string | null;
  actor_avatar: string | null;
}

interface NotificationsResponse {
  notifications: Notification[];
  total: number;
  unread_count: number;
}

interface UseNotificationsReturn {
  notifications: Notification[];
  total: number;
  unreadCount: number;
  isLoading: boolean;
  fetchNotifications: (skip?: number, take?: number) => Promise<void>;
  markAsRead: (notificationId: string) => Promise<void>;
  markAllAsRead: () => Promise<void>;
  fetchUnreadCount: () => Promise<void>;
}

export function useNotifications(): UseNotificationsReturn {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [total, setTotal] = useState(0);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isLoading, setIsLoading] = useState(false);

  const fetchNotifications = useCallback(async (skip: number = 0, take: number = 20) => {
    if (!authStorage.isAuthenticated()) return;

    const token = authStorage.getAccessToken();
    const cacheKey = `notifications:${skip}:${take}:${token}`;

    const cached = requestCache.get<NotificationsResponse>(cacheKey, 30000);
    if (cached) {
      setNotifications(cached.notifications);
      setTotal(cached.total);
      setUnreadCount(cached.unread_count);
      return;
    }

    setIsLoading(true);
    try {
      const data = await apiClient.get(
        `/notifications?skip=${skip}&take=${take}`
      ) as any;
      requestCache.set(cacheKey, data);
      setNotifications(data.notifications);
      setTotal(data.total);
      setUnreadCount(data.unread_count);
    } catch (error) {
      console.error('Error fetching notifications:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const markAsRead = useCallback(async (notificationId: string) => {
    if (!authStorage.isAuthenticated()) return;

    try {
      await apiClient.patch(`/notifications/${notificationId}/read`, {}) as any;
      setNotifications(prev =>
        prev.map(n => n.id === notificationId ? { ...n, is_read: true } : n)
      );
      setUnreadCount(prev => Math.max(0, prev - 1));
      requestCache.invalidatePattern('notifications:');
    } catch (error) {
      console.error('Error marking notification as read:', error);
    }
  }, []);

  const markAllAsRead = useCallback(async () => {
    if (!authStorage.isAuthenticated()) return;

    try {
      await apiClient.patch('/notifications/read-all', {}) as any;
      setNotifications(prev => prev.map(n => ({ ...n, is_read: true })));
      setUnreadCount(0);
      requestCache.invalidatePattern('notifications:');
    } catch (error) {
      console.error('Error marking all notifications as read:', error);
    }
  }, []);

  const fetchUnreadCount = useCallback(async () => {
    if (!authStorage.isAuthenticated()) return;

    const token = authStorage.getAccessToken();
    const cacheKey = `unread_count:${token}`;
    const cached = requestCache.get<number>(cacheKey, 60000);
    if (cached !== null) {
      setUnreadCount(cached);
      return;
    }

    try {
      const data = await apiClient.get('/notifications/unread-count') as any;
      requestCache.set(cacheKey, data.unread_count);
      setUnreadCount(data.unread_count);
    } catch (error) {
      console.error('Error fetching unread count:', error);
    }
  }, []);

  return {
    notifications,
    total,
    unreadCount,
    isLoading,
    fetchNotifications,
    markAsRead,
    markAllAsRead,
    fetchUnreadCount,
  };
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useSearch } from './useSearch';

const mockGet = vi.fn();
vi.mock('@api/client', () => ({
  apiClient: {
    get: (...args: any[]) => mockGet(...args),
  },
  authStorage: {
    isAuthenticated: vi.fn(() => true),
    getUserId: vi.fn(() => 'user-123'),
  },
}));

vi.mock('./useDebounce', () => ({
  useDebounce: (value: string, _ms: number) => value,
}));

function makeUser(overrides = {}) {
  return { id: 'u1', username: 'juan', avatar_url: null, bio: 'Bio', ...overrides };
}

describe('useSearch', () => {
  beforeEach(() => {
    mockGet.mockReset();
  });

  it('deber├¡a devolver estado inicial', () => {
    const { result } = renderHook(() => useSearch());

    expect(result.current.query).toBe('');
    expect(result.current.results).toEqual({ users: [], cases: [], hasMore: false });
    expect(result.current.isSearching).toBe(false);
    expect(result.current.hasSearched).toBe(false);
    expect(result.current.error).toBeNull();
    expect(result.current.searchType).toBe('ALL');
  });

  it('setQuery deber├¡a actualizar la query', () => {
    const { result } = renderHook(() => useSearch());

    act(() => {
      result.current.setQuery('test');
    });

    expect(result.current.query).toBe('test');
  });

  it('deber├¡a buscar cuando query >= minChars', async () => {
    const { result } = renderHook(() => useSearch());

    mockGet.mockResolvedValue({ following: [] });

    await act(async () => {
      await new Promise(r => setTimeout(r, 10));
    });

    mockGet.mockResolvedValue({ users: [makeUser()], cases: [], hasMore: false });

    act(() => {
      result.current.setQuery('ju');
    });

    await act(async () => {
      await new Promise(r => setTimeout(r, 100));
    });

    expect(result.current.results.users).toHaveLength(1);
    expect(mockGet).toHaveBeenLastCalledWith(
      expect.stringContaining('/search/advanced?q=ju')
    );
  });

  it('clearResults deber├¡a resetear todo y traer following', async () => {
    const { result } = renderHook(() => useSearch());

    mockGet.mockResolvedValue({ following: [] });

    await act(async () => {
      await new Promise(r => setTimeout(r, 10));
    });

    act(() => {
      result.current.clearResults();
    });

    expect(result.current.query).toBe('');
    expect(result.current.results).toEqual({ users: [], cases: [], hasMore: false });
    expect(result.current.error).toBeNull();
  });

  it('search() manual deber├¡a ejecutar b├║squeda', async () => {
    const { result } = renderHook(() => useSearch({ minChars: 2 }));

    mockGet.mockResolvedValue({ following: [] });

    await act(async () => {
      await new Promise(r => setTimeout(r, 10));
    });

    mockGet.mockResolvedValue({ users: [], cases: [{ id: 'c1', title: 'Caso' }], hasMore: false });

    act(() => {
      result.current.setQuery('consulta');
    });

    act(() => {
      result.current.search();
    });

    await act(async () => {
      await new Promise(r => setTimeout(r, 100));
    });

    expect(result.current.results.cases).toHaveLength(1);
  });

  it('deber├¡a manejar error en b├║squeda', async () => {
    const { result } = renderHook(() => useSearch());

    mockGet.mockResolvedValue({ following: [] });

    await act(async () => {
      await new Promise(r => setTimeout(r, 10));
    });

    mockGet.mockRejectedValueOnce(new Error('Server error'));

    act(() => {
      result.current.setQuery('error');
    });

    await act(async () => {
      await new Promise(r => setTimeout(r, 100));
    });

    expect(result.current.error).toBe('Server error');
  });

  it('setSearchType deber├¡a cambiar el tipo de b├║squeda', () => {
    const { result } = renderHook(() => useSearch());

    act(() => {
      result.current.setSearchType('USERS');
    });

    expect(result.current.searchType).toBe('USERS');
  });

  it('fetchFollowing deber├¡a manejar error de API', async () => {
    const { result } = renderHook(() => useSearch());
    mockGet.mockRejectedValueOnce(new Error('Following error'));
    await act(async () => { await new Promise(r => setTimeout(r, 10)); });
    expect(result.current.isSearching).toBe(false);
  });

  it('query vac├¡o deber├¡a mostrar following cuando autenticado', async () => {
    mockGet.mockResolvedValue({ following: [{ id: 'u1', username: 'testuser', avatar_url: null, bio: null }] });
    const { result } = renderHook(() => useSearch());
    await act(async () => { await new Promise(r => setTimeout(r, 10)); });
    act(() => { result.current.setQuery('a'); });
    await act(async () => { await new Promise(r => setTimeout(r, 10)); });
    act(() => { result.current.setQuery(''); });
    await act(async () => { await new Promise(r => setTimeout(r, 10)); });
    expect(mockGet).toHaveBeenCalledWith('/users/me/following?take=10');
  });

  it('deber├¡a limpiar AbortController al desmontar', () => {
    const { unmount } = renderHook(() => useSearch());
    expect(() => unmount()).not.toThrow();
  });

  it('search() no deber├¡a ejecutarse si query < minChars', () => {
    const { result } = renderHook(() => useSearch({ minChars: 3 }));
    mockGet.mockClear();
    act(() => { result.current.setQuery('ab'); });
    act(() => { result.current.search(); });
    expect(mockGet).not.toHaveBeenCalledWith(expect.stringContaining('/search/advanced'));
  });

  it('deber├¡a buscar con type CASES', async () => {
    mockGet.mockResolvedValue({ following: [] });
    const { result } = renderHook(() => useSearch());
    await act(async () => { await new Promise(r => setTimeout(r, 10)); });
    act(() => { result.current.setSearchType('CASES'); });
    mockGet.mockResolvedValue({ users: [], cases: [{ id: 'c1', title: 'Caso test', category: 'legal', status: 'PUBLIC' }], hasMore: false });
    act(() => { result.current.setQuery('test'); });
    await act(async () => { await new Promise(r => setTimeout(r, 100)); });
    expect(mockGet).toHaveBeenLastCalledWith(expect.stringContaining('type=CASES'));
  });
});

