              {languageDropdown && (
                <div className="absolute z-50 w-full mt-2 bg-card border border-border-main/5 rounded-2xl overflow-hidden">
                  {[
                    { code: 'es', label: 'Espa├▒ol', flag: '­ƒç¬­ƒç©' },
                    { code: 'en', label: 'English', flag: '­ƒç║­ƒç©' },
