function StatusBadge({ status }: Readonly<{ status: string }>) {
  const { t } = useTranslation();
  const colorMap: Record<string, string> = {
    COMPLETED: 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30',
    RUNNING: 'bg-sky-500/15 text-sky-400 border-sky-500/30',
    PENDING: 'bg-amber-500/15 text-amber-400 border-amber-500/30',
    PARTIAL: 'bg-orange-500/15 text-orange-400 border-orange-500/30',
    FAILED: 'bg-rose-500/15 text-rose-400 border-rose-500/30',
    CANCELLED: 'bg-zinc-500/15 text-zinc-400 border-zinc-500/30',
  };
  const key = `automation.runs.status.${status}`;
  const label = t(key, { defaultValue: status });

  let dotClass = 'bg-current';
  if (status === 'RUNNING') {
    dotClass = 'bg-sky-400 animate-pulse';
  } else if (status === 'COMPLETED') {
    dotClass = 'bg-emerald-400';
  } else if (status === 'FAILED') {
    dotClass = 'bg-rose-400';
  }

  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider rounded-full border',
        colorMap[status] || 'bg-zinc-500/15 text-zinc-400 border-zinc-500/30'
      )}
    >
      <span
        className={cn('w-1.5 h-1.5 rounded-full', dotClass)}
      />
      {label}
    </span>
  );
}

function KpiCard({
  icon: Icon,
  label,
  value,
  hint,
  tone = 'default',
}: Readonly<{
  icon: React.ElementType;
  label: string;
  value: React.ReactNode;
  hint?: React.ReactNode;
  tone?: 'default' | 'accent' | 'success' | 'warning';
}>) {
  const tones: Record<string, string> = {
    default: 'text-text-main',
    accent: 'text-sky-400',
    success: 'text-emerald-400',
    warning: 'text-amber-400',
  };
  return (
    <div className="bg-card border border-border-main/10 rounded-2xl p-4 flex items-start justify-between gap-3">
      <div className="min-w-0">
        <p className="text-[10px] font-bold text-text-muted uppercase tracking-wider truncate">
          {label}
        </p>
        <p className={cn('text-2xl font-black mt-1', tones[tone])}>{value}</p>
        {hint && (
          <p className="text-[11px] text-text-muted mt-1 truncate">{hint}</p>
        )}
      </div>
      <span className="p-2.5 rounded-xl bg-white/5 shrink-0">
        <Icon className="w-4 h-4 text-text-muted" />
      </span>
    </div>
  );
}

function Toggle({
  checked,
  disabled,
  onChange,
}: Readonly<{
  checked: boolean;
  disabled?: boolean;
  onChange: (value: boolean) => void;
}>) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      disabled={disabled}
      onClick={() => onChange(!checked)}
      className={cn(
        'relative inline-flex h-6 w-11 items-center rounded-full transition-colors shrink-0 disabled:opacity-50',
        checked ? 'bg-sky-500' : 'bg-white/10'
      )}
    >
      <span
        className={cn(
          'inline-block h-4 w-4 transform rounded-full bg-white transition-transform',
          checked ? 'translate-x-6' : 'translate-x-1'
        )}
      />
    </button>
  );
}

function formatWhen(value: string | null): string {
  if (!value) return 'ÔÇö';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return value;
  return d.toLocaleString();
}

export const AutomationPage: React.FC = () => {
  const { t } = useTranslation();
  const {
    canManage, settings, runs, queue, engagement,
    isLoadingSettings, isLoadingRuns, isLoadingQueue, isLoadingEngagement,
    isSavingSettings, isTriggeringRun, error, saveSettings, triggerRun,
    refreshAll, clearError, loadRun, runDetail, clearRunDetail,
  } = useAutomation();
  const { addToast } = useToast();

  const [dirty, setDirty] = useState<Record<string, unknown>>({});
  const [showConfig, setShowConfig] = useState(false);
  const [confirmRun, setConfirmRun] = useState(false);

  useEffect(() => {
    if (error) {
      addToast('error', t(error as string));
      clearError();
    }
  }, [error, addToast, clearError, t]);

  if (!canManage) {
    return (
      <PageLayout title={t('automation.title')}>
        <Seo title={t('automation.title')} />
        <div className="flex items-center justify-center h-full">
          <p className="text-text-muted text-sm px-6 text-center">
            {t('automation.accessDenied')}
          </p>
        </div>
      </PageLayout>
    );
  }

  const onChangeField = (field: string, value: unknown) => {
    setDirty((prev) => ({ ...prev, [field]: value }));
  };

  const handleSave = async () => {
    if (Object.keys(dirty).length === 0) {
      addToast('info', t('automation.toasts.noChanges'));
      return;
    }
    const ok = await saveSettings(dirty);
    if (ok) {
      setDirty({});
      addToast('success', t('automation.toasts.saved'));
    }
  };

  const handleTriggerRun = async (dryRun: boolean) => {
    if (!dryRun) {
      setConfirmRun(true);
      return;
    }
    const result = await triggerRun(dryRun);
    if (result) {
      addToast(
        'success',
        dryRun
          ? t('automation.toasts.runTriggeredDry')
          : t('automation.toasts.runTriggered')
      );
    }
  };

  const handleConfirmRun = async () => {
    setConfirmRun(false);
    const result = await triggerRun(false);
    if (result) {
      addToast('success', t('automation.toasts.runTriggered'));
    }
  };

  const handleOpenRun = async (id: string) => {
    await loadRun(id);
  };

  const topCases: AutomationCasePerformance[] = engagement?.topCases || [];

  const dryRunCasesCreated = () => {
    if (!runs || runs.length === 0) return 0;
    return runs
      .filter(r => r.dryRun)
      .reduce((acc, r) => acc + (r.casesCreated || 0), 0);
  };

  const realCasesCreated = () => {
    if (!runs || runs.length === 0) return 0;
    return runs
      .filter(r => !r.dryRun)
      .reduce((acc, r) => acc + (r.casesCreated || 0), 0);
  };

  const countByStatus = (status: string) =>
    runs.filter((r) => r.status === status).length;

  const isLoadingAny =
    isLoadingSettings || isLoadingRuns || isLoadingQueue || isLoadingEngagement;

  const renderConfigRow = (
    label: string,
    field: string,
    type: 'number' | 'bool' | 'text' | 'array' = 'number',
    hint?: string
  ) => {
    const current = (settings as any)?.[field];
    const value = field in dirty ? (dirty as any)[field] : current;

    const labelWithHint = hint ? (
      <Tooltip content={hint} position="right" delay={150}>
        <span className="flex items-center gap-1.5 cursor-help">
          <span className="text-sm text-text-main">{label}</span>
          <Info className="w-4 h-4 text-text-muted/50 flex-shrink-0" />
        </span>
      </Tooltip>
    ) : (
      <span className="text-sm text-text-main">{label}</span>
    );

    if (type === 'bool') {
      return (
        <div className="flex items-center justify-between gap-3 py-2">
          {labelWithHint}
          <Toggle
            checked={!!value}
            onChange={(v) => onChangeField(field, v)}
          />
        </div>
      );
    }

    if (type === 'array') {
      const joined = Array.isArray(value) ? value.join('\n') : '';
      return (
        <div className="py-2">
          {labelWithHint}
          <textarea
            value={joined}
            onChange={(e) =>
              onChangeField(
                field,
                e.target.value.split('\n').filter((l) => l.trim().length > 0)
              )
            }
            rows={3}
            className="mt-2 w-full bg-white/5 border border-border-main/10 rounded-xl px-3 py-2 text-sm text-text-main outline-none focus:border-sky-500/50"
          />
        </div>
      );
    }

    return (
      <div className="py-2">
        {labelWithHint}
        <input
          type="number"
          value={value ?? 0}
          onChange={(e) => onChangeField(field, Number(e.target.value))}
          className="mt-2 w-full bg-white/5 border border-border-main/10 rounded-xl px-3 py-2 text-sm text-text-main outline-none focus:border-sky-500/50"
        />
      </div>
    );
  };

  const totalPendingInteractions =
    (queue?.scheduled || 0) + (queue?.processing || 0);

  return (
    <PageLayout
      title={t('automation.title')}
      rightButton={{
        icon: RefreshCw,
        onClick: () => refreshAll(),
        tooltip: t('automation.refresh'),
        className: 'text-sky-400',
      }}
      showBackButton={false}
    >
      <Seo title={t('automation.title')} />
      <div className="px-6 py-6 space-y-8 max-w-5xl mx-auto">
        <div className="flex items-center gap-3">
          <span className="p-2.5 rounded-xl bg-sky-500/15">
            <Cpu className="w-5 h-5 text-sky-400" />
          </span>
          <div>
            <h1 className="text-lg font-black text-text-main">
              {t('automation.title')}
            </h1>
            <p className="text-xs text-text-muted">{t('automation.subtitle')}</p>
          </div>
        </div>

        {isLoadingAny && runs.length === 0 && !settings ? (
          <LoadingState />
        ) : (
          <>
            {/* KPIs */}
            <section>
              <SectionTitle>{t('automation.kpis')}</SectionTitle>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <KpiCard
                  icon={Zap}
                  label={t('automation.kpi.casesCreated')}
                  value={realCasesCreated()}
                  hint={
                    <>
                      <span className="font-bold text-emerald-400/80">{t('automation.kpi.realCases')}</span>
                      {dryRunCasesCreated() > 0 && (
                        <>
                          <span className="mx-1 text-amber-400">|</span>
                          <span className="font-bold text-amber-400/80">
                            {dryRunCasesCreated()} {t('automation.kpi.dryRunCases')}
                          </span>
                        </>
                      )}
                    </>
                  }
                  tone="success"
                />
                <KpiCard
                  icon={Activity}
                  label={t('automation.kpi.totalInteractions')}
                  value={totalPendingInteractions}
                  hint={t('automation.kpi.queueHint')}
                  tone="accent"
                />
                <KpiCard
                  icon={TrendingUp}
                  label={t('automation.kpi.avgScore')}
                  value={
                    engagement?.averageScore != null
                      ? Math.round(engagement.averageScore)
                      : 'ÔÇö'
                  }
                  hint={
                    engagement?.evaluatedCases
                      ? `${engagement.evaluatedCases} ${t('automation.kpi.evaluated')}`
                      : t('automation.kpi.noData')
                  }
                  tone="default"
                />
                <KpiCard
                  icon={ListChecks}
                  label={t('automation.kpi.runs')}
                  value={runs.length}
                  hint={`${countByStatus('COMPLETED')} ${t('automation.kpi.completed')}`}
                  tone="default"
                />
              </div>
            </section>

            {/* Acciones */}
            <section>
              <SectionTitle>{t('automation.actions')}</SectionTitle>
              <div className="flex flex-wrap gap-3">
                <button
                  type="button"
                  onClick={() => handleTriggerRun(false)}
                  disabled={isTriggeringRun}
                  className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-sky-500 hover:bg-sky-600 text-white text-sm font-bold transition-colors disabled:opacity-50"
                >
                  {isTriggeringRun ? (
                    <RefreshCw className="w-4 h-4 animate-spin" />
                  ) : (
                    <Play className="w-4 h-4" />
                  )}
                  {t('automation.runNow')}
                </button>
                <button
                  type="button"
                  onClick={() => setShowConfig((v) => !v)}
                  className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-white/5 hover:bg-white/10 text-text-main text-sm font-bold border border-border-main/10 transition-colors"
                >
                  <Settings2 className="w-4 h-4" />
                  {t('automation.configure')}
                  <ChevronDown
                    className={cn(
                      'w-4 h-4 transition-transform',
                      showConfig && 'rotate-180'
                    )}
                  />
                </button>
              </div>
            </section>

            {/* Config editor */}
            <AnimatePresence initial={false}>
              {showConfig && (
                <motion.section
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  exit={{ opacity: 0, height: 0 }}
                  className="overflow-hidden"
                >
                  <SectionTitle>{t('automation.config')}</SectionTitle>
                  {isLoadingSettings && !settings ? (
                    <LoadingState />
                  ) : (
                    <div className="bg-card border border-border-main/10 rounded-2xl p-5 space-y-3">
                      {renderConfigRow(t('automation.enabled'), 'enabled', 'bool', t('automation.hints.enabled'))}
                      {renderConfigRow(t('automation.dryRun'), 'dryRun', 'bool', t('automation.hints.dryRun'))}
                      {renderConfigRow(
                        t('automation.activityWeighted'),
                        'activityWeighted',
                        'bool',
                        t('automation.hints.activityWeighted')
                      )}
                      {renderConfigRow(
                        t('automation.engagementEnabled'),
                        'engagementEnabled',
                        'bool',
                        t('automation.hints.engagementEnabled')
                      )}
                      <div className="h-px bg-border-main/10 my-2" />
                      {renderConfigRow(t('automation.runHour'), 'runHour', 'number', t('automation.hints.runHour'))}
                      {renderConfigRow(t('automation.dailyCasesMin'), 'dailyCasesMin', 'number', t('automation.hints.dailyCasesMin'))}
                      {renderConfigRow(t('automation.dailyCasesMax'), 'dailyCasesMax', 'number', t('automation.hints.dailyCasesMax'))}
                      {renderConfigRow(t('automation.usersPerCaseMin'), 'usersPerCaseMin', 'number', t('automation.hints.usersPerCaseMin'))}
                      {renderConfigRow(t('automation.usersPerCaseMax'), 'usersPerCaseMax', 'number', t('automation.hints.usersPerCaseMax'))}
                      {renderConfigRow(
                        t('automation.schedulingIntervalMin'),
                        'schedulingIntervalMin',
                        'number',
                        t('automation.hints.schedulingIntervalMin')
                      )}
                      {renderConfigRow(
                        t('automation.schedulingIntervalMax'),
                        'schedulingIntervalMax',
                        'number',
                        t('automation.hints.schedulingIntervalMax')
                      )}
                      {renderConfigRow(
                        t('automation.schedulingWindowHours'),
                        'schedulingWindowHours',
                        'number',
                        t('automation.hints.schedulingWindowHours')
                      )}
                      {renderConfigRow(t('automation.intensityMin'), 'intensityMin', 'number', t('automation.hints.intensityMin'))}
                      {renderConfigRow(t('automation.intensityMax'), 'intensityMax', 'number', t('automation.hints.intensityMax'))}
                      {renderConfigRow(t('automation.dailyPoolSize'), 'dailyPoolSize', 'number', t('automation.hints.dailyPoolSize'))}
                      <div className="h-px bg-border-main/10 my-2" />
                      {renderConfigRow(t('automation.rssFeedUrls'), 'rssFeedUrls', 'array', t('automation.hints.rssFeedUrls'))}
                      <div className="pt-2 flex justify-end">
                        <button
                          type="button"
                          onClick={handleSave}
                          disabled={isSavingSettings || Object.keys(dirty).length === 0}
                          className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-bold transition-colors disabled:opacity-50"
                        >
                          {isSavingSettings ? (
                            <RefreshCw className="w-4 h-4 animate-spin" />
                          ) : (
                            <Check className="w-4 h-4" />
                          )}
                          {t('automation.save')}
                        </button>
                      </div>
                    </div>
                  )}
                </motion.section>
              )}
            </AnimatePresence>

            {/* Engagement */}
            <EngagementSection isLoading={isLoadingEngagement} topCases={topCases} />

            {/* Queue */}
            <section>
              <SectionTitle>{t('automation.queueTitle')}</SectionTitle>
              {isLoadingQueue && !queue ? (
                <LoadingState />
              ) : (
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                  <KpiCard
                    icon={Clock}
                    label={t('automation.queueMetrics.scheduled')}
                    value={queue?.scheduled ?? 0}
                  />
                  <KpiCard
                    icon={Activity}
                    label={t('automation.queueMetrics.processing')}
                    value={queue?.processing ?? 0}
                  />
                  <KpiCard
                    icon={Check}
                    label={t('automation.queueMetrics.completedToday')}
                    value={queue?.completedToday ?? 0}
                    tone="success"
                  />
                  <KpiCard
                    icon={X}
                    label={t('automation.queueMetrics.failedToday')}
                    value={queue?.failedToday ?? 0}
                    tone="warning"
                  />
                </div>
              )}
            </section>

            {/* Run history */}
            <RunHistorySection
              isLoading={isLoadingRuns}
              runs={runs}
              onOpenRun={handleOpenRun}
            />

            {/* Run detail */}
            <RunDetailModal run={runDetail} onClose={clearRunDetail} />
           </>
         )}
       </div>
       <ConfirmModal
         isOpen={confirmRun}
         onConfirm={handleConfirmRun}
         onCancel={() => setConfirmRun(false)}
         isLoading={isTriggeringRun}
         variant="warning"
         title={t('automation.confirmRun.title')}
         message={t('automation.confirmRun.message')}
         confirmLabel={t('automation.confirmRun.confirm')}
         cancelLabel={t('automation.confirmRun.cancel')}
       />
     </PageLayout>
   );
 };

function StatRow({ label, value }: Readonly<{ label: string; value: string | number }>) {
  return (
    <div className="flex items-center justify-between">
      <span className="text-text-muted">{label}</span>
      <span className="font-semibold text-text-main">{value}</span>
    </div>
  );
}

interface EngagementSectionProps {
  isLoading: boolean;
  topCases: AutomationCasePerformance[];
}

function EngagementSection({ isLoading, topCases }: Readonly<EngagementSectionProps>) {
  const { t } = useTranslation();
  return (
    <section>
      <SectionTitle>{t('automation.engagement')}</SectionTitle>
      {isLoading && !topCases.length && <LoadingState />}
      {!isLoading && topCases.length === 0 && (
        <EmptyState titleKey="automation.noEngagement" />
      )}
      {!isLoading && topCases.length > 0 && (
        <div className="bg-card border border-border-main/10 rounded-2xl overflow-hidden">
          <ul className="divide-y divide-border-main/10">
            {topCases.map((c) => (
              <li
                key={c.caseId}
                className="flex items-center gap-3 px-4 py-3 hover:bg-white/5"
              >
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold text-text-main truncate">
                    {c.title || c.caseId}
                  </p>
                  <p className="text-[11px] text-text-muted">
                    {c.votes} {t('automation.metrics.votes')} ┬À{' '}
                    {c.comments} {t('automation.metrics.comments')} ┬À{' '}
                    {c.reactions} {t('automation.metrics.reactions')} ┬À{' '}
                    {c.shares} {t('automation.metrics.shares')}
                  </p>
                </div>
                <div className="text-right shrink-0">
                  <p className="text-lg font-black text-emerald-400">
                    {c.engagementScore}
                  </p>
                  <p className="text-[10px] text-text-muted uppercase tracking-wider">
                    {t('automation.metrics.score')}
                  </p>
                </div>
              </li>
            ))}
          </ul>
        </div>
      )}
    </section>
  );
}

interface RunHistorySectionProps {
  isLoading: boolean;
  runs: AutomationRun[];
  onOpenRun: (id: string) => void;
}

function RunHistorySection({ isLoading, runs, onOpenRun }: Readonly<RunHistorySectionProps>) {
  const { t } = useTranslation();
  return (
    <section>
      <SectionTitle>{t('automation.history')}</SectionTitle>
      {isLoading && !runs.length && <LoadingState />}
      {!isLoading && runs.length === 0 && (
        <EmptyState titleKey="automation.noRuns" />
      )}
      {!isLoading && runs.length > 0 && (
        <div className="bg-card border border-border-main/10 rounded-2xl overflow-hidden">
          <ul className="divide-y divide-border-main/10">
            {runs.map((run) => (
              <li key={run.id}>
                <button
                  type="button"
                  onClick={() => onOpenRun(run.id)}
                  className="w-full text-left px-4 py-3 hover:bg-white/5 cursor-pointer"
                >
                  <div className="flex items-center justify-between gap-3">
                    <div className="flex items-center gap-3 min-w-0">
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-semibold text-text-main truncate">
                          {String(run.id).slice(0, 8)}
                          {run.dryRun && (
                            <span className="ml-2 text-[10px] font-bold text-amber-400 uppercase bg-amber-500/10 border border-amber-500/30 px-1.5 py-0.5 rounded-full">
                              dry
                            </span>
                          )}
                        </p>
                        <p className="text-[11px] text-text-muted">
                          {run.casesCreated}/{run.casesRequested}{' '}
                          {t('automation.metrics.cases')} ┬À{' '}
                          {formatWhen(run.startedAt)}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 shrink-0">
                      <StatusBadge status={run.status} />
                      <ChevronDown className="w-4 h-4 text-text-muted" />
                    </div>
                  </div>
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}
    </section>
  );
}

interface RunDetailModalProps {
  run: AutomationRun | null;
  onClose: () => void;
}

function RunDetailModal({ run, onClose }: Readonly<RunDetailModalProps>) {
  const { t } = useTranslation();
  return (
    <AnimatePresence>
      {run && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 bg-black/70 flex items-end md:items-center justify-center"
          onClick={onClose}
        >
          <motion.div
            initial={{ y: 40, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: 40, opacity: 0 }}
            onClick={(e) => e.stopPropagation()}
            className="bg-card border border-border-main/10 rounded-t-2xl md:rounded-2xl w-full max-w-lg max-h-[80vh] overflow-y-auto p-6"
          >
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-base font-black text-text-main uppercase tracking-wider">
                {t('automation.runDetail')}
              </h3>
              <button
                type="button"
                onClick={onClose}
                className="p-1.5 rounded-full hover:bg-white/10 text-text-muted"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="space-y-3 text-sm">
              <div className="flex items-center justify-between">
                <span className="text-text-muted">{t('automation.runs.status.status')}</span>
                <StatusBadge status={run.status} />
              </div>
              <StatRow label={t('automation.metrics.casesRequested')} value={run.casesRequested} />
              <StatRow label={t('automation.metrics.casesCreated')} value={run.casesCreated} />
              <StatRow label={t('automation.metrics.casesFailed')} value={run.casesFailed} />
              <StatRow
                label={t('automation.metrics.startedAt')}
                value={formatWhen(run.startedAt)}
              />
              <StatRow
                label={t('automation.metrics.finishedAt')}
                value={formatWhen(run.finishedAt)}
              />
              {run.errorMessage && (
                <div className="bg-rose-500/10 border border-rose-500/30 rounded-xl p-3 text-rose-300">
                  {run.errorMessage}
                </div>
              )}
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

export default AutomationPage;

/**
 * ============================================
 * redux/services/casesApi.ts ÔÇö RTK Query API de Casos
 * ============================================
 *
 * ┬┐Qu├® es?
 *   Es la fuente de verdad ├║nica del m├│dulo feed/detalle de casos.
 *   Reemplaza el tr├¡o de fuentes previas:
 *     - redux/slices/casesSlice (thunks legacy, sin consumidores)
 *     - hooks/useCases (estado local con cache vac├¡a)
 *     - llamadas apiClient directas en p├íginas
 *
 * ┬┐C├│mo funciona el feed infinito?
 *   - getFeed usa serializeQueryArgs para que skip NO participe de la
 *     clave de cache: una sola entrada por (tab, category, q).
 *   - forceRefetch pide al servidor cuando cambia skip (paginaci├│n).
 *   - merge concatena por id (dedup) cuando skip > 0 y reemplaza al
 *     resetear a skip 0 (cambio de tab/categor├¡a).
 *
 * ┬┐C├│mo se mantienen los contadores coherentes?
 *   Las mutaciones (votar, guardar, reaccionar) actualizan la cache
 *   v├¡a updateQueryData tanto en el feed como en el detalle, con los
 *   valores que devuelve el backend. No hace falta refetch manual.
 */

import { createApi } from '@reduxjs/toolkit/query/react';
import type { ThunkAction } from '@reduxjs/toolkit';
import type { UnknownAction } from 'redux';
import type { AppDispatch, RootState } from '../store';
import { authStorage } from '@api/client';
import type { Case, FeedTab } from '@typings/index';
import { mapDbCaseToCase } from '@services/mappers/caseMapper';
import { baseQuery } from './rtkApiClient';
import { toReactionCounts, type ReactionEmoji, type ReactionPayload } from './reactionContract';

// ============================================================
// Constantes
// ============================================================

export const FEED_PAGE_SIZE = 20;

/** Tama├▒o de p├ígina de las listas del perfil (created/saved/voted). */
export const PROFILE_PAGE_SIZE = 10;

// ============================================================
// Tipos p├║blicos
// ============================================================

export interface FeedArgs {
  tab: FeedTab;
  category: string;
  q: string;
  skip: number;
}

export interface FeedResult {
  cases: Case[];
  hasMore: boolean;
}

export interface VotePayload {
  vote_type: 'A' | 'B' | 'BOTH_WRONG' | null;
  votes_a: number;
  votes_b: number;
  votes_both_wrong: number;
}

export interface SavePayload {
  saved: boolean;
  anchorsCount: number;
}

/**
 * Payload de creaci├│n de caso. Va en camelCase porque as├¡ lo espera
 * CreateCaseRequest (core-domain-service). El backend NO persiste
 * evidence_urls (ese campo no existe en el DTO).
 */
export interface CreateCasePayload {
  type: 'vote' | 'classic';
  title: string;
  sideAContent: string;
  category?: string;
  isAnonymous?: boolean;
  sideBUserId?: string;
  sideASubtitle?: string;
  sideBSubtitle?: string;
  bothWrongSubtitle?: string;
}

/**
 * Payload de respuesta a invitaci├│n (Side B). Va en snake_case porque
 * as├¡ lo espera RespondSideBRequest. `caseId` es opcional y solo se usa
 * para invalidar la cache de getCase del caso respondido.
 */
export interface RespondCasePayload {
  invite_token: string;
  side_b_content: string;
  is_anonymous?: boolean;
  evidence_urls?: string[];
  caseId?: string;
}

/**
 * Shape de GET /cases/trending/top (sidebar). Se conserva snake_case del
 * backend porque el sidebar solo muestra t├¡tulo, categor├¡a, contajes y autor.
 */
export interface TrendingCase {
  id: string;
  title: string;
  slug?: string | null;
  category: string;
  votes_a: number;
  votes_b: number;
  votes_both_wrong: number;
  _count?: { comments: number; reactions: number };
  total_comments?: number;
  comments_count?: number;
  total_reactions?: number;
  reactions_summary?: { counts: { LIKE: number; LOVE: number; ANGRY: number } };
  side_a_user?: { username?: string; is_anonymous?: boolean; id?: string };
  side_a_username?: string;
}

/** Usuario activo del bloque "voting now" (GET /cases/active-users). */
export interface ActiveUser {
  id: string;
  username: string;
  avatar_url: string | null;
  is_anonymous: boolean;
}

export interface ActiveUsersResponse {
  users: ActiveUser[];
  total: number;
}

export interface UserCaseListArgs {
  username: string;
  skip: number;
  take: number;
}

export interface ProfileCaseListArgs {
  skip: number;
  take: number;
}

export interface CaseListResult {
  cases: Case[];
  hasMore: boolean;
}

// ============================================================
// API
// ============================================================

export const casesApi = createApi({
  reducerPath: 'casesApi',
  baseQuery,
  tagTypes: ['Case'],
  endpoints: (builder) => ({
    /**
     * Feed paginado. Una sola entrada de cache por (tab, category, q);
     * skip solo dispara refetch (forceRefetch) y merge concatena.
     */
    getFeed: builder.query<FeedResult, FeedArgs>({
      query: (args) => ({
        url: '/cases',
        params: {
          skip: args.skip,
          take: FEED_PAGE_SIZE,
          feedType: args.tab,
          category: args.category === 'All' ? '' : args.category,
          q: args.q,
        },
      }),
      serializeQueryArgs: ({ queryArgs }) => `${queryArgs.tab}|${queryArgs.category}|${queryArgs.q}`,
      transformResponse: (raw: unknown, _meta, args: FeedArgs) => {
        const currentUserId = authStorage.getUserId() ?? undefined;
        const cases = Array.isArray(raw)
          ? raw.map((caseData: Record<string, unknown>) => mapDbCaseToCase(caseData, currentUserId))
          : [];
        return { cases, hasMore: cases.length === FEED_PAGE_SIZE };
      },
      merge: (cache, incoming, { arg }) => {
        if (arg.skip === 0 || !cache) return incoming;
        const unique = new Map<string, Case>(cache.cases.map((c) => [c.id, c]));
        for (const next of incoming.cases) unique.set(next.id, next);
        return { cases: [...unique.values()], hasMore: incoming.hasMore };
      },
      forceRefetch: ({ currentArg, previousArg }) => currentArg?.skip !== previousArg?.skip,
      providesTags: (result) =>
        result ? result.cases.map((c) => ({ type: 'Case' as const, id: c.id })) : [],
    }),

    /**
     * Detalle de un caso (usado por CaseDetailPage). El argumento es la
     * clave de cache y a la vez el path del endpoint:
     *   - `/cases/:id`             ÔåÆ `/cases/' + id`
     *   - `/cases/:username/:slug` ÔåÆ `/cases/' + 'username/slug'`
     * Las mutaciones (voteCase/reactToCase/saveCase) parchean todas las
     * entradas de getCase cuya `data.id === caseId` (ver applyCasePatch),
     * cubriendo tanto cache por id como por slug.
     */
    getCase: builder.query<Case, string>({
      query: (key) => ({ url: `/cases/${key}` }),
      transformResponse: (raw: unknown) => {
        return mapDbCaseToCase(raw as Record<string, unknown>, authStorage.getUserId() ?? undefined);
      },
      providesTags: (_result, _error, id) => [{ type: 'Case' as const, id }],
    }),

    /**
     * Casos creados por un usuario (tab "created" del perfil). Paginaci├│n
     * infinita: serializa por username, forceRefetch al cambiar skip y merge
     * concatena (dedup por id). La cache es la fuente de verdad de la lista;
     * applyCasePatch mantiene voto/save/reacci├│n coherentes.
     */
    getUserCases: builder.query<CaseListResult, UserCaseListArgs>({
      query: ({ username, skip, take }) => ({
        url: `/users/${username}/cases`,
        params: { skip, take },
      }),
      serializeQueryArgs: ({ queryArgs }) => `user-cases|${queryArgs.username}`,
      transformResponse: (raw: unknown) => mapCaseListResponse(raw),
      merge: (cache, incoming, { arg }) => mergeCaseList(cache, incoming, arg.skip),
      forceRefetch: ({ currentArg, previousArg }) => currentArg?.skip !== previousArg?.skip,
    }),

    /**
     * Casos guardados del usuario logueado (tab "saved"). Cada item de la
     * respuesta trae `case_id` y `id`; el mapper normaliza a `id` el caso.
     */
    getSavedCases: builder.query<CaseListResult, ProfileCaseListArgs>({
      query: ({ skip, take }) => ({ url: '/saved-cases', params: { skip, take } }),
      serializeQueryArgs: () => 'saved-cases',
      transformResponse: (raw: unknown) => mapCaseListResponse(raw, { preferCaseId: true }),
      merge: (cache, incoming, { arg }) => mergeCaseList(cache, incoming, arg.skip),
      forceRefetch: ({ currentArg, previousArg }) => currentArg?.skip !== previousArg?.skip,
    }),

    /**
     * Casos donde el usuario logueado ha votado (tab "voted").
     */
    getUserVotes: builder.query<CaseListResult, ProfileCaseListArgs>({
      query: ({ skip, take }) => ({ url: '/users/me/votes', params: { skip, take } }),
      serializeQueryArgs: () => 'user-votes',
      transformResponse: (raw: unknown) => mapCaseListResponse(raw),
      merge: (cache, incoming, { arg }) => mergeCaseList(cache, incoming, arg.skip),
      forceRefetch: ({ currentArg, previousArg }) => currentArg?.skip !== previousArg?.skip,
    }),

    /**
     * Votar en un caso. Actualiza la cache del feed y del detalle
     * con los contadores que devuelve el backend.
     */
    voteCase: builder.mutation<VotePayload, { caseId: string; voteType: 'A' | 'B' | 'BOTH_WRONG' }>({
      query: ({ caseId, voteType }) => ({
        url: `/cases/${caseId}/votes`,
        method: 'POST',
        body: { vote_type: voteType },
      }),
      async onQueryStarted({ caseId }, { dispatch, getState, queryFulfilled }) {
        try {
          const { data } = await queryFulfilled;
          applyCasePatch(dispatch, getState, caseId, (draft) => {
            draft.votesA = data.votes_a;
            draft.votesB = data.votes_b;
            draft.votesBothWrong = data.votes_both_wrong;
            draft.userVote = data.vote_type;
          });
        } catch {
          // El error se propaga al caller; la cache queda como estaba.
        }
      },
    }),

    /**
     * Quitar el voto de un caso (mismo contrato que voteCase).
     */
    removeVote: builder.mutation<VotePayload, { caseId: string }>({
      query: ({ caseId }) => ({ url: `/cases/${caseId}/votes`, method: 'DELETE' }),
      async onQueryStarted({ caseId }, { dispatch, getState, queryFulfilled }) {
        try {
          const { data } = await queryFulfilled;
          applyCasePatch(dispatch, getState, caseId, (draft) => {
            draft.votesA = data.votes_a;
            draft.votesB = data.votes_b;
            draft.votesBothWrong = data.votes_both_wrong;
            draft.userVote = data.vote_type;
          });
        } catch {
          // El error se propaga al caller; la cache queda como estaba.
        }
      },
    }),

    /**
     * Anclar/desanclar un caso. transformResponse normaliza el
     * payload del backend ({ saved, caseResponse?.total_anchors }).
     */
    saveCase: builder.mutation<SavePayload, { caseId: string }>({
      query: ({ caseId }) => ({ url: `/saved-cases/${caseId}/save`, method: 'POST', body: {} }),
      transformResponse: (raw: Record<string, unknown>) => {
        const caseResponse = raw.caseResponse as Record<string, unknown> | undefined;
        return {
          saved: raw.saved === true,
          anchorsCount: typeof caseResponse?.total_anchors === 'number' ? caseResponse.total_anchors : 0,
        };
      },
      async onQueryStarted({ caseId }, { dispatch, getState, queryFulfilled }) {
        try {
          const { data } = await queryFulfilled;
          applyCasePatch(dispatch, getState, caseId, (draft) => {
            draft.isSaved = data.saved;
            draft.anchorsCount = data.anchorsCount;
          });
        } catch {
          // El error se propaga al caller; la cache queda como estaba.
        }
      },
    }),

    /**
     * Reaccionar a un caso (solo target_type CASE). Las reacciones a
     * comentarios van por commentsApi.reactToComment (cache de
     * comentarios, no de casos).
     */
    reactToCase: builder.mutation<ReactionPayload, { caseId: string; emoji: ReactionEmoji }>({
      query: ({ caseId, emoji }) => ({
        url: '/reactions',
        method: 'POST',
        body: { target_type: 'CASE', target_id: caseId, emoji },
      }),
      async onQueryStarted({ caseId }, { dispatch, getState, queryFulfilled }) {
        try {
          const { data } = await queryFulfilled;
          applyCasePatch(dispatch, getState, caseId, (draft) => {
            draft.reactions = toReactionCounts(data.reactions);
            draft.userReaction = data.user_reaction;
          });
        } catch {
          // El error se propaga al caller; la cache queda como estaba.
        }
      },
    }),

    /**
     * Crear un caso. El payload va en camelCase (CreateCaseRequest) y el
     * backend descarta evidence_urls. La respuesta se normaliza con
     * mapDbCaseToCase; el caller la inserta al feed con prependCaseToFeed.
     */
    createCase: builder.mutation<Case, CreateCasePayload>({
      query: (payload) => ({
        url: '/cases',
        method: 'POST',
        body: payload,
      }),
      transformResponse: (raw: unknown) => {
        return mapDbCaseToCase(raw as Record<string, unknown>, authStorage.getUserId() ?? undefined);
      },
    }),

    /**
     * Responder a una invitaci├│n como Side B (JoinCasePage). El payload va
     * en snake_case (RespondSideBRequest). Si se pasa `caseId`, al completar
     * se invalida la cache de getCase de ese id (estado WAITINGÔåÆPUBLIC).
     */
    respondCase: builder.mutation<Case, RespondCasePayload>({
      query: (payload) => ({
        url: '/cases/respond',
        method: 'POST',
        body: {
          invite_token: payload.invite_token,
          side_b_content: payload.side_b_content,
          is_anonymous: payload.is_anonymous,
          evidence_urls: payload.evidence_urls,
        },
      }),
      transformResponse: (raw: unknown) => {
        return mapDbCaseToCase(raw as Record<string, unknown>, authStorage.getUserId() ?? undefined);
      },
      invalidatesTags: (_result, _error, arg) =>
        arg.caseId ? [{ type: 'Case' as const, id: arg.caseId }] : [],
    }),

    /**
     * Casos en tendencia del sidebar (GET /cases/trending/top).
     */
    getTrendingCases: builder.query<TrendingCase[], void>({
      query: () => ({ url: '/cases/trending/top' }),
      transformResponse: (raw: unknown) => mapTrendingCases(raw),
    }),

    /**
     * Usuarios votando ahora (GET /cases/active-users). El sidebar lo
     * consume con polling de 30s; fuera del per├¡odo activo no se pide.
     */
    getActiveUsers: builder.query<ActiveUsersResponse, void>({
      query: () => ({ url: '/cases/active-users' }),
      transformResponse: (raw: unknown) => mapActiveUsers(raw),
    }),
  }),
});

// ============================================================
// Helpers de cache
// ============================================================

type CaseUpdater = (draft: Case) => void;

/**
 * Normaliza la respuesta de las listas del perfil. El backend devuelve un
 * array (disponible en GET /users/:username/cases y /users/me/votes) o un
 * objeto `{ cases, total }` (GET /saved-cases). Con preferCaseId=true se
 * normaliza el id desde `case_id` (shape de saved-cases).
 */
function mapCaseListResponse(raw: unknown, opts: { preferCaseId?: boolean } = {}): CaseListResult {
  const currentUserId = authStorage.getUserId() ?? undefined;
  const nested = (raw as Record<string, unknown> | undefined)?.cases;
  let list: unknown[] = [];
  if (Array.isArray(raw)) {
    list = raw;
  } else if (Array.isArray(nested)) {
    list = nested;
  }
  const cases = list.map((item) => {
    const c = item as Record<string, unknown>;
    const normalized: Record<string, unknown> = opts.preferCaseId
      ? { ...c, id: c.case_id ?? c.id }
      : c;
    return mapDbCaseToCase(normalized, currentUserId);
  });
  return { cases, hasMore: cases.length === PROFILE_PAGE_SIZE };
}

function optionalNumber(value: unknown): number | undefined {
  return typeof value === 'number' ? value : undefined;
}

/**
 * Normaliza el array de GET /cases/trending/top: garantiza los campos
 * n├║mericos y el autor del caso (side_a_user), dejando el resto del shape
 * del backend tal cual (el sidebar no usa un Case completo).
 */
function mapTrendingCases(raw: unknown): TrendingCase[] {
  const list = Array.isArray(raw) ? raw : [];
  return list.map((item) => {
    const row = item as Record<string, unknown>;
    return {
      id: String(row.id),
      title: typeof row.title === 'string' ? row.title : '',
      slug: row.slug as string | null | undefined,
      category: typeof row.category === 'string' ? row.category : 'Other',
      votes_a: Number(row.votes_a ?? 0),
      votes_b: Number(row.votes_b ?? 0),
      votes_both_wrong: Number(row.votes_both_wrong ?? 0),
      _count: row._count as TrendingCase['_count'],
      total_comments: optionalNumber(row.total_comments),
      comments_count: optionalNumber(row.comments_count),
      total_reactions: optionalNumber(row.total_reactions),
      reactions_summary: row.reactions_summary as TrendingCase['reactions_summary'],
      side_a_user: (row.side_a_user ?? {}) as TrendingCase['side_a_user'],
      side_a_username: row.side_a_username as string | undefined,
    };
  });
}

/**
 * Normaliza GET /cases/active-users ÔåÆ { users, total }. Tolera respuesta
 * sin `users` o con filas incompletas.
 */
function mapActiveUsers(raw: unknown): ActiveUsersResponse {
  const payload = (raw ?? {}) as Record<string, unknown>;
  const list = Array.isArray(payload.users) ? (payload.users as unknown[]) : [];
  return {
    users: list.map((item) => {
      const row = item as Record<string, unknown>;
      return {
        id: String(row.id),
        username: String(row.username),
        avatar_url: (row.avatar_url as string | null) ?? null,
        is_anonymous: row.is_anonymous === true,
      };
    }),
    total: Number(payload.total ?? 0),
  };
}

function mergeCaseList(cache: CaseListResult, incoming: CaseListResult, skip: number): CaseListResult {
  if (skip === 0 || !cache) return incoming;
  const unique = new Map<string, Case>(cache.cases.map((c) => [c.id, c]));
  for (const next of incoming.cases) unique.set(next.id, next);
  return { cases: [...unique.values()], hasMore: incoming.hasMore };
}

function getCachedFeedArgs(getState: () => unknown): FeedArgs[] {
  return casesApi.util.selectCachedArgsForQuery(getState() as never, 'getFeed') as FeedArgs[];
}

function getCachedDetailArgs(getState: () => unknown): string[] {
  return casesApi.util.selectCachedArgsForQuery(getState() as never, 'getCase') as string[];
}

/**
 * Aplica un cambio a un caso en las listas del perfil cacheadas
 * (getUserCases/getSavedCases/getUserVotes). selectCachedArgsForQuery
 * devuelve los arg originales de cada entrada; updateQueryData re-serializa
 * el arg para localizar su cache key (ver getFeed).
 */
function patchListCaches(dispatch: AppDispatch, getState: () => unknown, caseId: string, updater: CaseUpdater) {
  const patchWith = (draft: CaseListResult) => {
    const target = draft.cases.find((c) => c.id === caseId);
    if (target) updater(target);
  };

  const userArgs = casesApi.util.selectCachedArgsForQuery(getState() as never, 'getUserCases') as unknown as UserCaseListArgs[];
  for (const args of userArgs) {
    dispatch(casesApi.util.updateQueryData('getUserCases', args, patchWith));
  }
  const savedArgs = casesApi.util.selectCachedArgsForQuery(getState() as never, 'getSavedCases') as unknown as ProfileCaseListArgs[];
  for (const args of savedArgs) {
    dispatch(casesApi.util.updateQueryData('getSavedCases', args, patchWith));
  }
  const votedArgs = casesApi.util.selectCachedArgsForQuery(getState() as never, 'getUserVotes') as unknown as ProfileCaseListArgs[];
  for (const args of votedArgs) {
    dispatch(casesApi.util.updateQueryData('getUserVotes', args, patchWith));
  }
}

/**
 * Aplica un cambio a un caso en TODAS las entradas cacheadas que lo
 * contienen: feed (getFeed), detalle (getCase ÔÇö keyed por id o slug) y las
 * listas del perfil. No-op si la cache no existe a├║n.
 */
function forEachCachedCase(dispatch: AppDispatch, getState: () => unknown, caseId: string, updater: CaseUpdater) {
  for (const args of getCachedFeedArgs(getState)) {
    dispatch(
      casesApi.util.updateQueryData('getFeed', args, (draft) => {
        const target = draft.cases.find((c) => c.id === caseId);
        if (target) updater(target);
      })
    );
  }
  for (const key of getCachedDetailArgs(getState)) {
    dispatch(
      casesApi.util.updateQueryData('getCase', key, (draft) => {
        if (draft.id === caseId) updater(draft);
      })
    );
  }
  patchListCaches(dispatch, getState, caseId, updater);
}

function applyCasePatch(dispatch: AppDispatch, getState: () => unknown, caseId: string, updater: CaseUpdater) {
  forEachCachedCase(dispatch, getState, caseId, updater);
}

/**
 * Inserta un caso reci├®n creado al inicio de todas las entradas del feed.
 * Se exporta como thunk para usarse desde CreateCasePage.
 */
export function prependCaseToFeed(newCase: Case): ThunkAction<void, RootState, unknown, UnknownAction> {
  return (dispatch, getState) => {
    const feedArgsList = getCachedFeedArgs(getState);
    for (const args of feedArgsList) {
      dispatch(
        casesApi.util.updateQueryData('getFeed', args, (draft) => {
          draft.cases = [newCase, ...draft.cases];
        })
      );
    }
  };
}

/**
 * Incrementa sharesCount en todas las entradas cacheadas (feed, detalle y
 * listas del perfil). Se exporta como thunk para FeedPage (ShareModal).
 */
export function incrementCaseShareCount(caseId: string): ThunkAction<void, RootState, unknown, UnknownAction> {
  return (dispatch, getState) => {
    forEachCachedCase(dispatch as unknown as AppDispatch, getState, caseId, (draft) => {
      draft.sharesCount = (draft.sharesCount ?? 0) + 1;
    });
  };
}

/**
 * Incrementa commentsCount tras publicar un comentario (contador optimista).
 * Se exporta como thunk para ProfilePage y CaseDetailPage.
 */
export function incrementCaseCommentsCount(caseId: string): ThunkAction<void, RootState, unknown, UnknownAction> {
  return (dispatch, getState) => {
    forEachCachedCase(dispatch as unknown as AppDispatch, getState, caseId, (draft) => {
      draft.commentsCount = (draft.commentsCount ?? 0) + 1;
    });
  };
}

