describe('cn', () => {
  it('deber├¡a combinar clases simples', () => {
    expect(cn('p-4', 'text-red-500')).toBe('p-4 text-red-500');
  });

  it('deber├¡a resolver conflictos de Tailwind', () => {
    expect(cn('p-4', 'p-6')).toBe('p-6');
  });

  it('deber├¡a manejar clases condicionales', () => {
    expect(cn('p-4', false && 'hidden', 'm-2')).toBe('p-4 m-2');
  });

  it('deber├¡a devolver string vac├¡o sin argumentos', () => {
    expect(cn()).toBe('');
  });
});

describe('formatNumber', () => {
  it('deber├¡a formatear n├║meros menores a 1K', () => {
    expect(formatNumber(0)).toBe('0');
    expect(formatNumber(123)).toBe('123');
    expect(formatNumber(999)).toBe('999');
  });

  it('deber├¡a formatear miles como K', () => {
    expect(formatNumber(1000)).toBe('1K');
    expect(formatNumber(1500)).toBe('1.5K');
    expect(formatNumber(999500)).toBe('999.5K');
  });

  it('deber├¡a formatear millones como M', () => {
    expect(formatNumber(1000000)).toBe('1M');
    expect(formatNumber(2500000)).toBe('2.5M');
    expect(formatNumber(10000000)).toBe('10M');
  });

  it('deber├¡a eliminar decimal .0', () => {
    expect(formatNumber(1000)).toBe('1K');
    expect(formatNumber(1000000)).toBe('1M');
  });
});

describe('createSlug', () => {
  it('deber├¡a convertir a min├║sculas', () => {
    expect(createSlug('Hola Mundo')).toBe('hola-mundo');
  });

  it('deber├¡a eliminar tildes y diacr├¡ticos', () => {
    expect(createSlug('┬┐Qui├®n tiene la raz├│n?')).toBe('quien-tiene-la-razon');
    expect(createSlug('├ël corri├│ r├ípido')).toBe('el-corrio-rapido');
  });

  it('deber├¡a reemplazar espacios y especiales con guiones', () => {
    expect(createSlug('test   multiple   spaces')).toBe('test-multiple-spaces');
    expect(createSlug('special!@#characters')).toBe('special-characters');
  });

  it('deber├¡a limitar a 100 caracteres', () => {
    const long = 'a'.repeat(150);
    expect(createSlug(long).length).toBeLessThanOrEqual(100);
  });

  it('deber├¡a eliminar guiones al inicio y final', () => {
    expect(createSlug(' -hola- ')).toBe('hola');
  });
});

describe('getCasePath', () => {
  it('deber├¡a generar URL sem├íntica con username y t├¡tulo', () => {
    const result = getCasePath({
      id: '123',
      title: '┬┐Qui├®n tiene la raz├│n?',
      sideA: { username: 'juanperez' }
    });
    expect(result).toBe('/cases/juanperez/quien-tiene-la-razon');
  });

  it('deber├¡a caer a /cases/:id si falta username', () => {
    const result = getCasePath({
      id: '123',
      title: 'Test Case',
      sideA: {}
    });
    expect(result).toBe('/cases/123');
  });

  it('deber├¡a caer a /cases/:id si falta t├¡tulo', () => {
    const result = getCasePath({
      id: '123',
      sideA: { username: 'juanperez' }
    });
    expect(result).toBe('/cases/123');
  });

  it('deber├¡a codificar username con caracteres especiales', () => {
    const result = getCasePath({
      id: '123',
      title: 'Test',
      sideA: { username: 'usuario ├▒o├▒o' }
    });
    expect(result).toContain(encodeURIComponent('usuario ├▒o├▒o'));
  });
});

describe('formatRelativeCaseDate', () => {
  it('deber├¡a retornar "justo ahora" para menos de 1 minuto', () => {
    expect(formatRelativeCaseDate(new Date().toISOString())).toBe('justo ahora');
  });

  it('deber├¡a retornar hace X min para menos de 1 hora', () => {
    const date = new Date(Date.now() - 5 * 60 * 1000);
    expect(formatRelativeCaseDate(date.toISOString())).toBe('hace 5 min');
  });

  it('deber├¡a retornar hace Xh para menos de 24 horas', () => {
    const date = new Date(Date.now() - 3 * 3600 * 1000);
    expect(formatRelativeCaseDate(date.toISOString())).toBe('hace 3h');
  });

  it('deber├¡a retornar hace Xd para menos de 7 d├¡as', () => {
    const date = new Date(Date.now() - 2 * 86400 * 1000);
    expect(formatRelativeCaseDate(date.toISOString())).toBe('hace 2d');
  });

  it('deber├¡a retornar fecha formateada para 7+ d├¡as', () => {
    const date = new Date('2024-01-15');
    const result = formatRelativeCaseDate(date.toISOString());
    expect(result).toMatch(/\d{1,2}/);
  });

  it('deber├¡a aceptar Date object', () => {
    expect(formatRelativeCaseDate(new Date())).toBe('justo ahora');
  });

  it('deber├¡a retornar string original para fecha inv├ílida', () => {
    expect(formatRelativeCaseDate('not-a-date')).toBe('not-a-date');
  });

  it('deber├¡a retornar string vac├¡o para Date inv├ílido', () => {
    expect(formatRelativeCaseDate(new Date('invalid'))).toBe('');
  });

  it('deber├¡a respetar locale para fechas antiguas', () => {
    const date = new Date('2024-01-15');
    const result = formatRelativeCaseDate(date.toISOString(), 'es');
    expect(result).toContain('ene');
  });
});

describe('sleep', () => {
  it('deber├¡a devolver una Promise', () => {
    const result = sleep(0);
    expect(result).toBeInstanceOf(Promise);
  });

  it('deber├¡a resolver despu├®s del tiempo especificado', async () => {
    const start = Date.now();
    await sleep(5);
    expect(Date.now() - start).toBeGreaterThanOrEqual(4);
  });
});
